export default function Dashboard() {
  const [activeTab, setActiveTab] = useState<'commander' | 'campaigns' | 'history' | 'team' | 'scanner'>('commander');
  const [drawerTab, setDrawerTab] = useState<'audit' | 'design' | 'email'>('audit');
  const [team] = useState<TeamMember[]>(MOCK_TEAM);
  const [businesses, setBusinesses] = useState<Business[]>([]);
  const [leads, setLeads] = useState<Business[]>([]);
  const [selectedProvince, setSelectedProvince] = useState<string>('Barcelona');
  const [selectedCity, setSelectedCity] = useState<string>('Llinars del Vallès');
  const [selectedBusiness, setSelectedBusiness] = useState<Business | null>(null);
  const [scanning, setScanning] = useState(false);
  const [selectedNiche, setSelectedNiche] = useState('Servicios Locales');
  const [selectedCompanyType, setSelectedCompanyType] = useState<'pyme' | 'empresa' | 'autonomo' | 'corporativo'>('pyme');
  const [operationArea, setOperationArea] = useState('Llinars del Vallès, Barcelona');
  const [sending, setSending] = useState(false);

  const sendEmail = async (business: Business) => {
    if (!business.email && !business.intel?.foundEmails?.length) {
      autopilot.addMissionLog("⚠️ No se ha detectado email para este contacto.", "warning");
      return;
    }

    setSending(true);
    autopilot.addMissionLog(`📤 Iniciando disparo de auditoría para ${business.name}...`, "info", true);

    try {
      const targetEmail = business.email || business.intel?.foundEmails[0];
      const resp = await fetch('/api/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: targetEmail,
          name: business.name,
          location: business.address,
          analysisData: {
            gap: business.intel?.findings[0] || 'Optimización de Conversión',
            loss: business.intel?.estimatedLossLabel || 'Impacto Crítico',
            marketPotential: business.intel?.marketPotential || 'ALTO',
            pitch: business.draftEmail || `Hola, hemos analizado ${business.name} y detectado una oportunidad de crecimiento estratégica.`
          },
          isTest: true 
        })
      });

      const data = await resp.json();
      if (data.success) {
        autopilot.addMissionLog(`✅ ÉXITO: Reporte estratégico enviado a ${targetEmail}`, "success");
        setBusinesses(prev => prev.map(b => b.id === business.id ? { ...b, status: 'high' } : b));
      } else {
        throw new Error(data.error || "Fallo en el servidor de correo");
      }
    } catch (err) {
      console.error(err);
      autopilot.addMissionLog("❌ EL DISPARO HA FALLADO: Revisa la conexión con Resend.", "warning");
    } finally {
      setSending(false);
    }
  };

  // Hook de Autopilot (El Cerebro)
  const autopilot = useAutopilot({ 
    leads: businesses, 
    selectedNiche, 
    location: operationArea || selectedNeighborhood,
    activeTab,
    selectedCompanyType,
    setActiveTab,
    onLeadSynced: (syncedLead) => {
      setLeads(prev => {
        const index = prev.findIndex(l => l.id === syncedLead.id);
        if (index >= 0) {
          const updated = [...prev];
          updated[index] = syncedLead;
