  <div className="absolute inset-0 flex items-center justify-center pointer-events-none -z-10">
    <motion.div 
      initial={{ scale: 0.5, opacity: 0.5 }}
      animate={{ scale: 3, opacity: 0 }}
      transition={{ duration: 3, repeat: Infinity, ease: "easeOut" }}
      className="absolute w-20 h-20 rounded-full border border-primary/40 bg-primary/5"
    />
    <motion.div 
      initial={{ scale: 0.5, opacity: 0.3 }}
      animate={{ scale: 2.5, opacity: 0 }}
      transition={{ duration: 3, repeat: Infinity, ease: "easeOut", delay: 1 }}
      className="absolute w-20 h-20 rounded-full border border-secondary/30 bg-secondary/5"
    />
  </div>
);

export const SmallTrendGraph = ({ color = "rose" }: { color?: "rose" | "emerald" }) => (
  <svg width="40" height="20" viewBox="0 0 40 20" className={cn("opacity-60", color === 'rose' ? "text-rose-500" : "text-emerald-500")}>
    <motion.path 
      initial={{ pathLength: 0 }}
      animate={{ pathLength: 1 }}
      transition={{ duration: 1, ease: "easeInOut" }}
      d="M0 15 L8 12 L16 18 L24 4 L32 10 L40 2" 
      fill="none" 
      stroke="currentColor" 
      strokeWidth="2"
      strokeLinecap="round"
    />
  </svg>
);

export function ChatBubble({ role, text, delay }: { role: 'user' | 'ai', text: string, delay: number }) {
  return (
    <motion.div
      initial={{ opacity: 0, x: role === 'user' ? -20 : 20, scale: 0.8 }}
      animate={{ opacity: 1, x: 0, scale: 1 }}
      transition={{ delay }}
      className={cn(
        "max-w-[80%] p-4 rounded-3xl text-sm leading-relaxed",
        role === 'user' ? "bg-slate-800 text-slate-300 self-start" : "bg-primary text-white self-end rounded-tr-none ml-auto"
      )}
    >
      {text}
    </motion.div>
  );
}

export function ProblemItem({ text }: { text: string }) {
  return (
    <div className="flex items-center gap-3 text-slate-300 text-sm bg-slate-800/40 p-3 rounded-2xl border border-white/5">
