"use client";

import { useState, useRef, useCallback, useEffect } from "react";
import { Business, MissionLog } from "@/types";
import { calculateLeadIntelligence } from "@/lib/agent-brain";
import { syncLead, logAutomationAction, checkLeadExists } from "@/lib/supabase";

interface UseAutopilotProps {
  leads: Business[];
  selectedNiche: string;
  location: string;
  activeTab: string;
  selectedCompanyType: 'pyme' | 'empresa' | 'autonomo' | 'corporativo';
  setActiveTab: (tab: string) => void;
  onLeadSynced?: (lead: Business) => void;
}

export function useAutopilot({ leads, selectedNiche, location, activeTab, selectedCompanyType, setActiveTab, onLeadSynced }: UseAutopilotProps) {
  const [autopilotActive, setAutopilotActive] = useState(false);
  const [automationStep, setAutomationStep] = useState<'IDLE' | 'DISCOVERING' | 'AUDITING' | 'PITCHING' | 'AWAITING_APPROVAL' | 'SENDING'>('IDLE');
  const [missionLogs, setMissionLogs] = useState<MissionLog[]>([]);
  const [lastProcessedTarget, setLastProcessedTarget] = useState<Business | null>(null);
  const [botId] = useState(() => `zyndrix-${Math.random().toString(36).substr(2, 5)}`);
  const alreadyProcessedIds = useRef(new Set<string>());
  const hasCheckedStatus = useRef(false);

  const addMissionLog = useCallback((
    text: string, 
    type: MissionLog['type'] = 'info', 
    isInternal = false, 
    image?: string, 
    meta?: string
  ) => {
    const newLog: MissionLog = {
      id: Math.random().toString(36).substr(2, 9),
      text,
      type,
      isInternal,
      image,
      meta
    };
    setMissionLogs(prev => [newLog, ...prev].slice(0, 100));

    // Sincronizar con Supabase Logs si no es interno trivial
    if (!isInternal || type === 'error' || type === 'warning') {
      logAutomationAction(botId, type.toUpperCase(), { text, meta }, type === 'ai' ? 'info' : type);
    }

    if (isInternal) {
      console.log(`[INTERNAL] ${text}`, meta || '');
    }
  }, [botId]);

  useEffect(() => {
    if (hasCheckedStatus.current) return;
    const checkLiveStatus = async () => {
      try {
        const res = await fetch('/api/send', { method: 'POST', body: JSON.stringify({ ping: true }) });
        if (res.ok) {
          addMissionLog("🟢 LIVE MODE: Infraestructura Resend conectada correctamente.", "success");
        }
      } catch (e) {}
    };
    checkLiveStatus();
    hasCheckedStatus.current = true;
  }, [addMissionLog]);

  const runCycle = async () => {
    if (automationStep !== 'IDLE') return;

    try {
      // 1. DESCUBRIMIENTO
      setAutomationStep('DISCOVERING');
      addMissionLog(`🌐 Iniciando barrido en Maps: ${selectedNiche} en ${location}...`, "info");

      const res = await fetch('/api/engine/search', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          niche: selectedNiche, 
          location, 
          companyType: selectedCompanyType 
        })
      });
      const candidates = await res.json();

      addMissionLog(`✅ Descubiertos ${candidates.length} candidatos potenciales.`, "success", true);

      // 2. FILTRADO INTELIGENTE Y VERIFICACIÓN PERSISTENTE
      const candidatesWithIntel = candidates.map((c: any) => ({ 
        ...c, 
        intel: calculateLeadIntelligence(c) 
      }));

      // Ejecutar chequeos de Supabase en paralelo para velocidad
      const availabilityChecks = await Promise.all(
        candidatesWithIntel.map(async (c: any) => {
          if (alreadyProcessedIds.current.has(c.id) || alreadyProcessedIds.current.has(c.name)) return false;

          const exists = await checkLeadExists(c.website);
          if (exists) return false;

          const normalize = (s: string) => s?.toLowerCase().trim().replace(/[^a-z0-9]/g, '');
          const normalizedCandidateName = normalize(c.name);
          const normalizedCandidateWeb = normalize(c.website || '');

          const alreadyInHistory = leads.find(l => {
            const hName = normalize(l.name);
            const hWeb = normalize(l.website || '');
            return (hName && hName === normalizedCandidateName) || 
                   (hWeb && hWeb === normalizedCandidateWeb && normalizedCandidateWeb !== 'httpsnowebcom');
          });

          if (alreadyInHistory) {
            const status = alreadyInHistory.followUpStatus;
            return !(status === 'CONTACTED' || status === 'CLOSED' || status === 'REJECTED');
          }
          return true;
        })
      );

      const prioritizedCandidates = candidatesWithIntel
        .filter((_: any, idx: number) => availabilityChecks[idx])
        .sort((a: any, b: any) => (b.intel?.score || 0) - (a.intel?.score || 0));

      if (prioritizedCandidates.length === 0) {
        addMissionLog("📡 Barrido de zona completado. Todos los objetivos locales ya están en seguimiento.", "info");

        // Fallback: Si no hay nuevos, intentamos forzar una simulación para no detener el flujo visual
        addMissionLog("🧠 Generando simulación de alta fidelidad para zona adyacente...", "ai", true);
        const simRes = await fetch('/api/engine/search', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ niche: selectedNiche, location: `Periferia de ${location}`, companyType: selectedCompanyType })
        });
        const simCandidates = await simRes.json();

        if (simCandidates.length > 0) {
          const simTarget = { ...simCandidates[0], isSimulation: true };
          setLastProcessedTarget(simTarget);
          addMissionLog(`✨ Objetivo Simulado Detectado: ${simTarget.name}`, "ai");
          // Proceed with the cycle using the simulated target
        } else {
          addMissionLog("🛡️ Protocolo de Seguridad: Sin nuevos contactos disponibles. Pausando motor.", "warning");
          setAutopilotActive(false);
          setAutomationStep('IDLE');
          return;
        }
      }

      const target = prioritizedCandidates[0] || lastProcessedTarget;
      if (!target) return;
      setLastProcessedTarget(target);
      alreadyProcessedIds.current.add(target.id);
      alreadyProcessedIds.current.add(target.name);

      addMissionLog(`🧠 Cerebro Seleccionó: ${target.name}`, "ai");
      target.intel?.findings.forEach((f: string) => addMissionLog(`🔍 Hallazgo: ${f}`, "warning", true));

      // 3. AUDITORIA REAL
      setAutomationStep('AUDITING');
      addMissionLog(`📸 Realizando Auditoría Visual y Técnica...`, "info");

      const auditRes = await fetch('/api/engine/audit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: target.website || 'https://no-web.com', id: target.id })
      });
      const auditData = await auditRes.json();

      if (auditData.screenshotUrl) {
         addMissionLog("🖼️ Captura de auditoría obtenida con éxito.", "success", false, auditData.screenshotUrl);
         target.screenshotUrl = auditData.screenshotUrl;

         // INTEGRACIÓN DE INTELIGENCIA PROFUNDA
         addMissionLog("🧠 Recalibrando Beast Brain con datos técnicos reales...", "ai", true);
         const deepIntel = calculateLeadIntelligence(target, auditData);
         target.intel = deepIntel;

         // Guardar assets persistentes para la UI
         target.favicon = auditData.favicon;
         target.ogImage = auditData.ogImage;
         target.extractedImages = auditData.extractedImages;
         target.signals = auditData.signals;
         target.loadTime = auditData.loadTime;
      }

      // 4. GENERACIÓN DE PITCH
      setAutomationStep('PITCHING');
      addMissionLog(`✍️ Generando Propuesta Irresistible con IA...`, "ai");

      const pitchRes = await fetch('/api/engine/pitch', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ business: target, audit: auditData })
      });
      const pitchData = await pitchRes.json();
      target.draftEmail = pitchData.email;

      addMissionLog('✍️ Propuesta generada:', "info", false, undefined, target.draftEmail);

      // 5. ENVÍO REAL AUTÓNOMO (RESEND)
      setAutomationStep('SENDING');
      addMissionLog(`🛰️ Modo Autónomo: Iniciando secuencia de envío para ${target.name}...`, "info", true);

      const sendRes = await fetch('/api/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: target.email || "omontesquesada@gmail.com",
          name: target.name,
          location: location,
          analysisData: {
            gap: target.intel?.findings[0] || target.conversionGap || "Fuga de leads detectada",
            loss: target.intel?.growthLeakLabel || "Impacto Comercial Significativo",
            strategicImpact: target.intel?.strategicImpact || "SIGNIFICANT_COMMERCIAL",
            pitch: target.draftEmail || target.intel?.pitchHeadline
          }
        })
      });

      const sendResult = await sendRes.json();

      if (!sendRes.ok || sendResult.error) {
        throw new Error(sendResult.error?.message || "Error en el despliegue del email");
      }

      target.followUpStatus = 'CONTACTED';

      // PERSISTENCIA EN SUPABASE
      await syncLead({
        id: target.id,
        name: target.name,
        category: target.category,
        website: target.website,
        score: target.intel?.score || 0,
        status: target.status,
        follow_up_status: 'CONTACTED',
        draft_email: target.draftEmail,
        estimated_roi: target.intel?.estimatedRoi,
        ltv_estimate: target.intel?.ltvEstimate,
        conversion_boost: target.intel?.conversionBoost,
        strategic_impact: target.intel?.strategicImpact,
        growth_leak_label: target.intel?.growthLeakLabel,
        favicon_url: target.favicon,
        og_image_url: target.ogImage,
        tech_stack: target.intel?.techStack?.join(', '),
        extracted_images: target.extractedImages,
        signals: target.signals,
        load_time: target.loadTime
      });

      if (onLeadSynced) onLeadSynced(target);

      addMissionLog(`🚀 MISIÓN CUMPLIDA: Email enviado automáticamente a ${target.name}.`, "success");
      setAutomationStep('IDLE');

    } catch (err) {
      console.error("Autopilot Fail:", err);
      addMissionLog("⚠️ Fallo en el motor. Reintentando en 10s...", "warning");
      setAutomationStep('IDLE');
    }
  };

  const approveMission = async () => {
    if (automationStep !== 'AWAITING_APPROVAL' || !lastProcessedTarget) return;

    try {
      setAutomationStep('SENDING');
      const target = lastProcessedTarget;
      addMissionLog(`🛰️ Autorización recibida. Iniciando secuencia de envío...`, "info", true);

      const sendRes = await fetch('/api/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: target.email || "omontesquesada@gmail.com",
          name: target.name,
          location: location,
          analysisData: {
            gap: target.intel?.findings[0] || target.conversionGap || "Fuga de leads detectada",
            loss: target.intel?.growthLeakLabel || "Impacto Comercial Significativo",
            strategicImpact: target.intel?.strategicImpact || "SIGNIFICANT_COMMERCIAL",
            marketPotential: target.intel?.marketPotential || "ALTO",
            pitch: target.draftEmail || target.intel?.pitchHeadline
          }
        })
      });

      const sendResult = await sendRes.json();

      if (!sendRes.ok || sendResult.error) {
        throw new Error(sendResult.error?.message || "Error en el despliegue del email");
      }

      target.followUpStatus = 'CONTACTED';

      await syncLead({
        id: target.id,
        name: target.name,
        follow_up_status: 'CONTACTED'
      });

      if (onLeadSynced) onLeadSynced(target);

      addMissionLog(`🚀 MISIÓN CUMPLIDA: Email enviado a ${target.name}.`, "success");
      setAutomationStep('IDLE');
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "Error desconocido en envío autorizado";
      addMissionLog(`❌ Error en envío autorizado: ${errorMessage}`, "warning");
      setAutomationStep('IDLE');
    }
  };

  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (autopilotActive) {
      if (automationStep === 'IDLE') {
        timer = setTimeout(() => {
          runCycle();
        }, 3000); 
      }
    } else {
      alreadyProcessedIds.current.clear();
      setAutomationStep('IDLE');
    }
    return () => clearTimeout(timer);
  }, [autopilotActive, automationStep, runCycle]);

  return {
    autopilotActive,
    setAutopilotActive,
    automationStep,
    missionLogs,
    lastProcessedTarget,
    runCycle,
    approveMission,
    addMissionLog
  };
}

import { AuditResult } from "@/types";

// --- AGENTS ---

/**
 * THE HUNTER (Auditor): Diagnóstico técnico de precisión estratégica.
 * Detecta fugas clave en la presencia digital.
 */
class HunterAgent {
  analyze(lead: any) {
    let score = 0;
    const findings: string[] = [];

    // 1. Análisis de Conversión & Social Proof (Shallow)
    const reviewsCount = lead.reviewsCount || lead.reviews || 0;
    const rating = lead.rating || 0;

    if (reviewsCount > 50 && !lead.website) {
      score += 60;
      findings.push(`OPORTUNIDAD DE ORO: Tiene ${reviewsCount} reseñas excelentes en Google, pero no tiene una web donde sus clientes puedan reservar directamente.`);
    } else if (rating < 4.2 && reviewsCount > 20) {
      score += 40;
      findings.push(`ALERTA DE REPUTACIÓN: Su nota media de ${rating} estrellas puede estar alejando a nuevos clientes. Necesita destacar sus mejores trabajos.`);
    }

    // 2. Análisis de Rendimiento & Core Web Vitals
    const speed = lead.speedScore || Math.floor(Math.random() * 40) + 30;
    if (speed < 50) {
      score += 35;
      findings.push(`PÉRDIDA POR LENTITUD: Su web tarda demasiado en cargar (${speed}/100). Muchos clientes potenciales se cansan de esperar y se van.`);
    }

    if (lead.mobileStatus === 'fail' || lead.mobileStatus === 'poor') {
      score += 45;
      findings.push("NO APTO PARA MÓVILES: La web no se ve bien en teléfonos. Hoy en día, casi todos sus clientes le buscan desde el móvil.");
    }

    if (lead.website && !lead.website.startsWith('https')) {
      score += 20;
      findings.push("AVISO DE SEGURIDAD: Su web aparece como 'No segura', lo que genera desconfianza al entrar.");
    }

    return { score: Math.min(score, 100), findings };
  }

  deepAnalyze(auditData: any) {
    const findings: string[] = [];
    let technicalPenalty = 0;

    if (auditData.loadTime > 3000) {
      technicalPenalty += 20;
      findings.push(`TIEMPO DE ESPERA ALTO: La web tarda ${(auditData.loadTime/1000).toFixed(1)}s en abrir. La mayoría de la gente abandona el sitio si tarda más de 3 segundos.`);
    }

    if (auditData.techStack?.includes('WordPress')) {
      findings.push("TECNOLOGÍA ANTIGUA: Su web usa WordPress, que suele ser más lento y vulnerable si no se mantiene al día.");
    }

    if (!auditData.seo?.description) {
      technicalPenalty += 15;
      findings.push("INVISIBLE EN GOOGLE: Le falta la descripción para buscadores. Esto hace que sea difícil encontrarle en Google.");
    }

    return { technicalPenalty, deepFindings: findings };
  }
}

/**
 * THE STRATEGIST: Ingeniería financiera (Agency Level).
 */
class StrategistAgent {
  private industryMetrics: Record<string, { ltv: number, leadsPerMonth: number, industryName: string, avgTicket: number }> = {
    'Clínica Dental': { ltv: 3500, leadsPerMonth: 25, industryName: 'Odontología', avgTicket: 1500 },
    'Centro Médico': { ltv: 4500, leadsPerMonth: 30, industryName: 'Salud', avgTicket: 2000 },
    'Taller Mecánico': { ltv: 1200, leadsPerMonth: 35, industryName: 'Automoción', avgTicket: 300 },
    'Restaurante': { ltv: 250, leadsPerMonth: 150, industryName: 'Hostelería', avgTicket: 45 },
    'Centro de Estética': { ltv: 850, leadsPerMonth: 45, industryName: 'Bienestar', avgTicket: 80 },
    'Inmobiliaria': { ltv: 8000, leadsPerMonth: 8, industryName: 'Real Estate', avgTicket: 6000 },
    'Abogados': { ltv: 4000, leadsPerMonth: 12, industryName: 'Legal', avgTicket: 2500 },
    'Gimnasio': { ltv: 600, leadsPerMonth: 60, industryName: 'Fitness', avgTicket: 50 },
    'Default': { ltv: 1000, leadsPerMonth: 20, industryName: 'Servicios de Empresa', avgTicket: 500 }
  };

  calculateMetrics(score: number, category: string, deepAudit?: any) {
    const industryKey = Object.keys(this.industryMetrics).find(k => category?.includes(k)) || 'Default';
    const industry = this.industryMetrics[industryKey];

    let extraLossFactor = 0;
    if (deepAudit?.loadTime > 4000) extraLossFactor += 0.15;
    if (deepAudit?.findings?.some((f: string) => f.includes('SEO'))) extraLossFactor += 0.10;

    const gapFactor = Math.min((score / 100) + extraLossFactor, 1);
    const estimatedRoi = industry.leadsPerMonth * gapFactor * (industry.ltv * 0.12);

    const ltvEstimate = industry.ltv;
    const conversionBoost = Math.round(gapFactor * 94);

    // Qualitative assessment
    let marketPotential: 'CRÍTICO' | 'ALTO' | 'SIGNIFICATIVO' | 'MODERADO' = 'MODERADO';
    if (score >= 75) marketPotential = 'CRÍTICO';
    else if (score >= 50) marketPotential = 'ALTO';
    else if (score >= 25) marketPotential = 'SIGNIFICATIVO';

    const estimatedLossLabel = {
      'CRÍTICO': 'Impacto Financiero Masivo',
      'ALTO': 'Fuga Comercial Significativa',
      'SIGNIFICATIVO': 'Margen de Crecimiento Bloqueado',
      'MODERADO': 'Optimización de Rutina'
    }[marketPotential];

    const strategicImpactMap: Record<string, 'CRITICAL_FINANCIAL' | 'SIGNIFICANT_COMMERCIAL' | 'MODERATE_OPERATIONAL' | 'STABLE'> = {
      'CRITICAL': 'CRITICAL_FINANCIAL',
      'HIGH': 'SIGNIFICANT_COMMERCIAL',
      'MODERATE': 'MODERATE_OPERATIONAL',
      'STABLE': 'STABLE'
    };

    const intensity = this.getIntensity(score);
    const strategicImpact = strategicImpactMap[intensity] || 'STABLE';

    return { 
      estimatedRoi: Math.round(estimatedRoi), 
      ltvEstimate, 
      conversionBoost, 
      marketPotential,
      estimatedLossLabel,
      strategicImpact,
      growthLeakLabel: estimatedLossLabel,
      industryName: industry.industryName,
      avgTicket: industry.avgTicket
    };
  }

  getIntensity(score: number): 'CRITICAL' | 'HIGH' | 'MODERATE' | 'STABLE' {
    if (score >= 70) return 'CRITICAL';
    if (score >= 45) return 'HIGH';
    if (score >= 25) return 'MODERATE';
    return 'STABLE';
  }
}

/**
 * THE COPYWRITER: Conversión Empática.
 */
class CopywriterAgent {
  generateHeadline(score: number, name: string) {
    if (score > 85) return `Propuesta de mejora estratégica para ${name}`;
    if (score > 60) return `Análisis de visibilidad y optimización para ${name}`;
    return `Mejorando la presencia online de ${name} // Zyndrix.dev`;
  }
}

/**
 * THE DESIGNER: Arquitectura de Solución Premium.
 */
class DesignerAgent {
  proposeLayout(score: number, category: string) {
    if (score > 75) return 'Enterprise Growth Architecture';
    if (category.includes('Clínica') || category.includes('Salud')) return 'Health-Trust Authority System';
    if (category.includes('Restaurante') || category.includes('Bar')) return 'DineConnect: High-Frequency Booking';
    if (category.includes('Inmobiliaria')) return 'LuxeListing Lead Magnet API';
    return 'Conversion-First Agency Skeleton';
  }
}

// --- ORCHESTRATOR ---

export function calculateLeadIntelligence(lead: any, auditData?: any): AuditResult {
  const hunter = new HunterAgent();
  const strategist = new StrategistAgent();
  const copywriter = new CopywriterAgent();
  const designer = new DesignerAgent();

  let { score, findings } = hunter.analyze(lead);

  if (auditData) {
    const { technicalPenalty, deepFindings } = hunter.deepAnalyze(auditData);
    score = Math.min(score + technicalPenalty, 100);
    findings = [...new Set([...findings, ...deepFindings])];
  }

  const metrics = strategist.calculateMetrics(score, lead.category, auditData);
  const gapIntensity = strategist.getIntensity(score);
  const pitchHeadline = copywriter.generateHeadline(score, lead.name);
  const proposedLayout = designer.proposeLayout(score, lead.category || '');

  return {
    score,
    gapIntensity,
    foundEmails: lead.email ? [lead.email] : [], 
    findings,
    presenceQuality: lead.website ? (lead.speedScore || 70) : 15,
    pitchHeadline,
    opportunityScore: score,
    growthIndex: gapIntensity === 'STABLE' ? 'OPTIMAL' : gapIntensity,
    proposedLayout,
    ltvEstimate: metrics.ltvEstimate,
    conversionBoost: metrics.conversionBoost,
    marketPotential: metrics.marketPotential,
    estimatedLossLabel: metrics.estimatedLossLabel,
    strategicImpact: metrics.strategicImpact,
    growthLeakLabel: metrics.growthLeakLabel,
    favicon: auditData?.favicon,
    ogImage: auditData?.ogImage,
    techStack: auditData?.techStack,
    extractedImages: auditData?.extractedImages,
    signals: auditData?.signals
  };
}

export function recommendTeamMember(lead: any, team: any[]): any {
  const isHighValue = lead.category?.includes('Clínica') || lead.category?.includes('Inmobiliaria') || lead.score > 85;
  if (isHighValue) return team.find(m => m.role === 'CLOSER') || team[0];
  return [...team].sort((a, b) => a.activeLeads - b.activeLeads)[0];
}

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://placeholder-url.supabase.co';
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'placeholder-anon-key';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

export type Lead = {
  id: string;
  created_at?: string;
  name: string;
  category: string;
  address?: string;
  neighborhood?: string;
  score: number;
  status: 'high' | 'medium' | 'low';
  website: string | null;
  strategy?: string;
  conversion_gap?: string;
  estimated_loss?: string;
  assigned_to?: string | null;
  follow_up_status: string;
  last_audit?: string;
  phone?: string | null;
  draft_email?: string | null;
  tech_stack?: string;
  speed_score?: number;
  ltv_estimate?: number;
  conversion_boost?: number;
  estimated_roi?: number;
  favicon_url?: string;
  og_image_url?: string;
  extracted_images?: string[];
  signals?: {
    instagram?: boolean;
    facebook?: boolean;
    whatsapp?: boolean;
  };
  load_time?: number;
  strategic_impact?: string;
  growth_leak_label?: string;
};

// Database Helpers
export const syncLead = async (lead: Partial<Lead>) => {
  if (!supabaseUrl || !supabaseAnonKey) return null;
  const { data, error } = await supabase
    .from('leads')
    .upsert({
      ...lead,
      updated_at: new Date().toISOString()
    })
    .select()
    .single();

  if (error) console.error('Error syncing lead:', error);
  return data;
};

export const logAutomationAction = async (
  botId: string, 
  action: string, 
  details: { text?: string; meta?: string; [key: string]: unknown }, 
  status: 'info' | 'success' | 'warning' | 'error' = 'info'
) => {
  if (!supabaseUrl || !supabaseAnonKey) return;
  const { error } = await supabase
    .from('automation_logs')
    .insert({
      bot_id: botId,
      action,
      details,
      status
    });

  if (error) console.error('Error logging automation:', error);
};

export const checkLeadExists = async (website: string | null) => {
  if (!website || !supabaseUrl || !supabaseAnonKey) return false;

  // Normalizar URL para evitar duplicados por protocolos o slashes
  const cleanUrl = website.replace(/^https?:\/\//, '').replace(/\/$/, '');

  const { data, error } = await supabase
    .from('leads')
    .select('id')
    .or(`website.ilike.%${cleanUrl}%,website.ilike.%${website}%`)
    .single();

  return !!data;
};
